SELECT e.id, e.amount, e.expense_date, e.description, e.created_at, e.updated_at,
       c.id   AS category_id,
       c.name AS category_name,
       pc.id   AS parent_category_id,
       pc.name AS parent_category_name
FROM expenses e
JOIN categories c  ON e.category_id = c.id
LEFT JOIN categories pc ON c.parent_id = pc.id


        AND e.expense_date >= #{query.startDate}


        AND e.expense_date <= #{query.endDate}


        AND e.category_id = #{query.categoryId}


ORDER BY e.expense_date DESC, e.created_at DESC
LIMIT #{query.size} OFFSET #{query.offset}

SELECT COUNT(*) FROM expenses e


        AND e.expense_date >= #{query.startDate}


        AND e.expense_date <= #{query.endDate}


        AND e.category_id = #{query.categoryId}
